import sys

def can_avoid_ships(n, m, ships):
    positions = [0] * (2 * n + 1)
    for x1, x2, y in ships:
        for x in range(x1, x2 + 1):
            positions[x + n] += 1

    def dfs(time):
        if time == n:
            return True
        pos = positions[time]
        if pos > 0:
            if dfs(time + 1):
                return True
            if dfs(time + 2):
                return True
            if dfs(time + 3):
                return True
        elif pos == 0:
            if dfs(time + 1):
                return True
            if dfs(time + 2):
                return True
        return False

    result = []
    def reconstruct_path(time):
        if time == n:
            return
        pos = positions[time]
        if pos > 0:
            if dfs(time + 1):
                result.append('-')
                reconstruct_path(time + 1)
            elif dfs(time + 2):
                result.append('+')
                reconstruct_path(time + 2)
            else:
                result.append('0')
                reconstruct_path(time + 3)
        elif pos == 0:
            if dfs(time + 1):
                result.append('-')
                reconstruct_path(time + 1)
            else:
                result.append('+')
                reconstruct_path(time + 2)

    if not dfs(0):
        return "impossible"
    reconstruct_path(0)
    return ''.join(result[::-1])

