import sys

def can_dodge_ships(n, m, ships):
    # Check if it's possible to dodge all ships
    for i in range(1, n + 1):
        positions = set()
        for x1, x2, y in ships:
            if i >= abs(x1) and i >= abs(x2):
                positions.add((i, y))
        if len(positions) == m:
            return False
    return True

def find_path(n, m, ships):
    # If it's impossible to dodge, return "impossible"
    if not can_dodge_ships(n, m, ships):
        return "impossible"

    # Construct the path
    path = []
    for t in range(1, n + 1):
        for x1, x2, y in ships:
            if t >= abs(x1) and t >= abs(x2):
                if (t, y) in path:
                    continue
                elif (t - 1, y + 1) in path or (t + 1, y + 1) in path:
                    continue
                else:
                    path.append((t, y))
                    break
        else:
            path.append((t, None))

    # Convert path to instructions
    instructions = []
    x, y = 0, 0
    for t, y_next in path:
        if y_next is not None:
            if x < y_next:
                instructions.append('+')
            elif x > y_next:
                instructions.append('-')
            else:
                instructions.append('0')
        x = t
    return ''.join(instructions)

